let rawText = $json.content.parts[0].text.trim();
if (rawText.startsWith('```json')) {
  rawText = rawText.replace(/^```json/, '').replace(/```$/, '').trim();
} else if (rawText.startsWith('```')) {
  rawText = rawText.replace(/^```/, '').replace(/```$/, '').trim();
}

let parsed;
try {
  parsed = JSON.parse(rawText);
} catch (e) {
  parsed = {
    title: 'Bài viết Facebook EGGU',
    content: rawText,
    poster_headline: 'NÓNG HỔI VỪA THỔI VỪA ĂN',
    poster_subline: 'Bánh mì brioche nướng bơ tỏi đẫm trứng fluffy và phô mai',
    poster_badge: 'BÁN CHẠY NHẤT',
    theme: $('Code - Thu Thập Ảnh Thật (FB, IG, Threads, Web)').item.json.suggestedTheme || 'street_bold',
    dish: $('Code - Thu Thập Ảnh Thật (FB, IG, Threads, Web)').item.json.dishName,
    status: 'Chờ duyệt',
    created_at: new Date().toISOString()
  };
}

const dishInfo = $('Code - Thu Thập Ảnh Thật (FB, IG, Threads, Web)').item.json;
const chosenTheme = parsed.theme || dishInfo.suggestedTheme || 'street_bold';
const headline = parsed.poster_headline || 'NÓNG HỔI VỪA THỔI VỪA ĂN';
const subline = parsed.poster_subline || (dishInfo.dishName + ' - Bánh nướng bơ tỏi giòn rụm');
const badge = parsed.poster_badge || 'BÁN CHẠY NHẤT';

// Tạo link Poster Đồ Họa 1080x1080 do Code sinh ra từ CHÍNH BỨC ẢNH THẬT
const posterUrl = 'http://localhost:3000/api/marketing/poster?' +
  'dish=' + encodeURIComponent(dishInfo.dishName) +
  '&price=' + encodeURIComponent(dishInfo.dishPrice) +
  '&headline=' + encodeURIComponent(headline) +
  '&subline=' + encodeURIComponent(subline) +
  '&badge=' + encodeURIComponent(badge) +
  '&theme=' + encodeURIComponent(chosenTheme) +
  '&image=' + encodeURIComponent(dishInfo.photoUrl);

return [
  {
    json: {
      title: parsed.title || ('EGGU - ' + dishInfo.dishName),
      dishName: dishInfo.dishName,
      dishCategory: dishInfo.photoSource,
      dishPrice: dishInfo.dishPrice,
      targetAngle: dishInfo.targetAngle,
      content: parsed.content || rawText,
      realPhotoUrl: dishInfo.photoUrl,
      aiPhotoUrl: posterUrl,
      posterTheme: chosenTheme,
      status: 'PENDING',
      'Mã bài viết': 'FB-' + Date.now(),
      'Tiêu đề': parsed.title || ('EGGU - ' + dishInfo.dishName),
      'Món ăn': dishInfo.dishName + ' (Giá web: ' + dishInfo.dishPrice + ')',
      'Nguồn ảnh thật': dishInfo.photoSource,
      'Nội dung Facebook (Đã biên tập)': parsed.content || rawText,
      '📸 ẢNH THẬT (FB / IG / Threads)': dishInfo.photoUrl,
      '🎨 POSTER ĐỒ HỌA 1080x1080 (AI & Code sinh từ ảnh thật)': posterUrl,
      'Phong cách Poster': chosenTheme,
      'Gợi ý đăng bài': 'Nhân viên có thể tải ảnh thật hoặc poster đồ họa 1080x1080 để đăng Fanpage!',
      'Trạng thái': 'Chờ nhân viên copy',
      'Thời gian tạo': new Date().toLocaleString('vi-VN')
    }
  }
];
